    'about1.p5' => 'जल में घुलने वाली तरल को अलग करने में जटिलताएं होती हैं, जिन्हें गहराई से समझने, अनुभव और उत्पादों की आवश्यकता होती है जो न केवल वांछित परिणाम प्राप्त कर सकते हैं बल्कि लंबे समय तक लगातार और लागत प्रभावी ढंग से उन्हें प्रदान कर सकते हैं।',
    'about1.p6' => 'हमारी उत्पाद श्रृंखला में Polyelectrolytes, Activated Carbon, RO & MEE Antiscalants, MEE एंटीफोम, Defoamers, Bacterial Culture, कूलिंग टॉवर और बॉयलर वाटर ट्रीटमेंट केमिकल्स, Odour Control Chemicals और अन्य कई उत्पाद शामिल हैं। हम न केवल इन उत्पादों की आपूर्ति करते हैं बल्कि उन्हें ETP के बाकी हिस्सों के साथ एकीकृत करने में भी मदद करते हैं।',
    'about1.p7' => 'हमारे सफलता के पीछे मुख्य कारण यह है कि हम अपने ग्राहकों को उनकी जल और अपशिष्ट जल उपचार संयंत्रों में उनकी विशिष्ट समस्याओं या चुनौतियों के अनुसार अनुकूलित उत्पाद और सेवाएँ प्रदान करने में सक्षम हैं। हम विस्तृत उपचार-योग्यता अध्ययन करते हैं और हमारे ग्राहक को उनके जल और अपशिष्ट जल उपचार प्रणालियों में आने वाली चुनौतियों को दूर करने में मदद करने के लिए सबसे किफायती समाधान तैयार करते हैं। हम न केवल इन उत्पादों की आपूर्ति करते हैं बल्कि उन्हें शेष जल और/या अपशिष्ट जल उपचार प्रक्रिया के साथ एकीकृत करने में भी मदद करते हैं।',
    'about1.p8' => 'हम जल और अपशिष्ट जल उपचार और पुनर्चक्रण के क्षेत्र में सर्वोत्तम और नवीनतम, अत्याधुनिक प्रौद्योगिकियों और उत्पादों को अपने ग्राहकों तक पहुँचाकर हमेशा बाजार में अग्रणी बने रहने का प्रयास करेंगे।',
    'about1.p9' => 'हम हमेशा अपने ग्राहकों को उत्कृष्ट सेवा के साथ उत्कृष्ट प्रदर्शन करने वाले उत्पादों की आपूर्ति करेंगे।',
    'about1.p10' => 'हम हमेशा उस प्रतिमान के प्रति प्रतिबद्ध रहेंगे कि परिणाम मापने योग्य होने चाहिए, समाधान पर भरोसा नहीं किया जा सकता है, और ऐसे उत्पाद और समाधान प्रदान किए जाने चाहिए जो टिकाऊ हों, न केवल पर्यावरणीय रूप से बल्कि आर्थिक रूप से भी।',
    'about1.p11' => 'हम हमेशा अपने ग्राहकों से अर्जित धन से अर्जित धन की मात्रा की तुलना में अपने ग्राहकों के लिए बचाए गए धन की मात्रा के आधार पर अपनी सफलता को मापेंगे।',
    'about1.title' => 'लगभग <strong> Raybon Chemicals </strong>',
    'about1.mission.title' => 'उद्देश्य कथन',
    'about2.p2' => 'हम एक ऐसी कंपनी हैं जो न केवल अपने द्वारा आपूर्ति किए जाने वाले उत्पादों पर, बल्कि उत्पाद के साथ प्रदान की जाने वाली सेवाओं पर भी गर्व करती है।',
    'about2.p3' => 'हमारा आदर्श वाक्य हमेशा रहा हैः "उत्कृष्ट सेवा के साथ उत्कृष्ट पॉलिमर को पीछे छोड़ना" <strong> </strong>',
    'about2.p4' => '250 से अधिक कर्मचारियों के साथ, समूह के भीतर, हमारे इंजीनियर, रसायनज्ञ, तकनीशियन और क्षेत्र कर्मी हैं जो सटीक खुराक सुनिश्चित कर सकते हैं और क्षेत्र में हमारे रसायनों के उत्कृष्ट परिणाम प्राप्त कर सकते हैं। हमारे पास अपनी प्रयोगशाला है और गुणवत्तापूर्ण उत्पादों और सेवाओं के साथ-साथ विश्वसनीय रसद सुनिश्चित करने के लिए हम सीधे आपसे संपर्क करते हैं।',
    'about2.p5' => 'हमारे ग्राहकों में ल्यूपिन, ज़ायडस कैडिला, ग्रासिम इंडस्ट्रीज़, सन फार्मा, पी.आई. इंडस्ट्रीज़, टोरेंट, एच.पी.सी.एल. आदि जैसे विभिन्न निजी और सार्वजनिक क्षेत्र के उपक्रम शामिल हैं।',
    'about2.p6' => 'हमारे उत्पाद Polyelectrolytes, Defoamers, एंटीस्कैलेंट्स, डीवेटेरिंग polyelectrolytes, डी-ऑइलिंग polyelectrolytes, Bacterial cultures आदि जैसे विशेष रसायन हैं।',
    'about2.aims.intro' => 'हम अपने भागीदारों के साथ दीर्घकालिक पारस्परिक लाभकारी संबंधों में विश्वास करते हैं, और हमारे अधिकांश ग्राहक 15-20 वर्षों से अधिक समय से हमारे ग्राहक रहे हैं, जो इस बात के प्रमाण हैं। हमारे उद्देश्य हमारे साझेदारों के उद्देश्य के साथ निकटता से जुड़े हुए हैं, अर्थात् अपने ग्राहकों को सेवा प्रदान करना।',
    'about2.aims.1' => 'बेहतर डेटा दृश्यता',
    'about2.aims.2' => 'उत्पादकता में वृद्धि',
    'about2.aims.3' => 'कम लागत',
    'about2.aims.4' => 'बेहतर पर्यावरणीय प्रदर्शन',
    'about2.aims.5' => 'बेहतर लाभ',
    'about2.aims.6' => 'बेहतर संपत्ति सुरक्षा',
    'about2.p8' => 'हमने सदैव यह माना है कि जब तक परिणाम मापनीय नहीं होंगे, तब तक समाधान पर विश्वास नहीं किया जा सकता, इसलिए हम सदैव उपयोग किए गए रसायनों के प्रति किलोग्राम लागत पर ध्यान देने के बजाय खुराक और उपचार दर पर जोर देते हैं।',
    'about2.p9' => 'हमने भारत में "केमिकल्स एज़ ए सर्विस" (सी.ए.ए.एस.) व्यवसाय मॉडल की अवधारणा और प्रतिमान को अग्रणी बनाया है और हम दृढ़ता से मानते हैं कि समय के साथ इस अवधारणा को बाजार में स्वीकृति मिलेगी।',
];
